import{d as r,C as l,o,c as s,j as a,a as i,E as d,a3 as h}from"./chunks/framework.Q4yG9rk_.js";const f=JSON.parse('{"title":"荀子·第6篇·非十二子","description":"《荀子·非十二子》——批评诸家学说，申明所持的儒学立场。","frontmatter":{"title":"荀子·第6篇·非十二子","description":"《荀子·非十二子》——批评诸家学说，申明所持的儒学立场。","category":"guide","aliases":["荀子非十二子","荀子第6篇"],"source":["维基文库《荀子/非十二子篇》，修订号 380277"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/xunzi/chapter-06.md","filePath":"lizhimingde/xunzi/chapter-06.md","lastUpdated":1794362429000}'),p={name:"lizhimingde/xunzi/chapter-06.md"},x=r({...p,setup(u){const t=[{id:"p001",sentences:[["假今之世，饰邪说，文奸言，以枭乱天下，矞宇嵬琐，使天下混然不知是非治乱之所在者有人矣。纵情性，安恣睢，禽兽行，不足以合文通治；然而其持之有故，其言之成理，足以欺惑愚众，是它嚻、魏牟也。忍情性，綦谿利跂，苟以分异人为高，不足以合大众，明大分；然而其持之有故，其言之成理，足以欺惑愚众，是陈仲、史䲡也。不知壹、天下建国家之权称，上功用、大俭约而僈差等，曾不足以容辨异、县君臣；然而其持之有故，其言之成理，足以欺惑愚众，是墨翟、宋銒也。尚法而无法，下修而好作，上则取听于上，下则取从于俗，终日言成文典，反𬘓察之，则倜然无所归宿，不可以经国定分；然而其持之有故，其言之成理，足以欺惑愚众，是慎到、田骈也。不法先王，不是礼义，而好治怪说，玩琦辞，甚察而不惠，辩而无用，多事而寡功，不可以为治纲纪；然而其持之有故，其言之成理，足以欺惑愚众，是惠施、邓析也。略法先王而不知其统，犹然而材剧志大，闻见杂博。案往旧造说，谓之五行，甚僻违而无类，幽隐而无说，闭约而无解。案饰其辞而祗敬之曰：此真先君子之言也。子思唱之，孟轲和之，世俗之沟犹瞀儒，嚾嚾然不知其所非也，遂受而传之，以为仲尼、子游为兹厚于后世，是则子思、孟轲之罪也。若夫总方略，齐言行，壹统类，而群天下之英杰而告之以大古，教之以至顺，奥窔之闲，簟席之上，敛然圣王之文章具焉，佛然平世之俗起焉，六说者不能入也，十二子者不能亲也，无置锥之地而王公不能与之争名，在一大夫之位则一君不能独畜，一国不能独容，成名况乎诸侯，莫不愿以为臣，是圣人之不得埶者也，仲尼、子弓是也。一天下，财万物，长养人民，兼利天下，通达之属，莫不从服，六说者立息，十二子者迁化，则圣人之得埶者，舜、禹是也。今夫仁人也，将何务哉？上则法舜、禹之制，下则法仲尼、子弓之义，以务息十二子之说，如是则天下之害除，仁人之事毕，圣王之迹著矣。"]]},{id:"p002",sentences:[["信信，信也；疑疑，亦信也。贵贤，仁也；贱不肖，亦仁也。言而当，知也；默而当，亦知也。故知默犹知言也。故多言而类，圣人也；少言而法，君子也；多言无法而流湎然，虽辩，小人也。故劳力而不当民务谓之奸事，劳知而不律先王谓之奸心，辩说譬谕、齐给便利而不顺礼义谓之奸说。此三奸者，圣王之所禁也。知而险，贼而神，为诈而巧，言无用而辩，辩不惠而察，治之大殃也。行辟而坚，饰非而好，玩奸而泽，言辩而逆，古之大禁也。知而无法，勇而无惮，察辩而操僻淫，大而用之，好奸而与众，利足而迷，负石而坠，是天下之所弃也。"]]},{id:"p003",sentences:[["兼服天下之心：高上尊贵不以骄人，聪明圣知不以穷人，齐给速通不争先人，刚毅勇敢不以伤人；不知则问，不能则学，虽能必让，然后为德。遇君则修臣下之义，遇乡则修长幼之义，遇长则修子弟之义，遇友则修礼节辞让之义，遇贱而少者则修告导宽容之义。无不爱也，无不敬也，无与人争也，恢然如天地之苞万物，如是则贤者贵之，不肖者亲之。如是而不服者，则可谓訞怪狡猾之人矣，虽则子弟之中，刑及之而宜。《诗》云：“匪上帝不时，殷不用旧。虽无老成人，尚有典刑。曾是莫听，大命以倾。”此之谓也。"]]},{id:"p004",sentences:[["古之所谓仕士者，厚敦者也，合群者也，乐富贵者也，乐分施者也，远罪过者也，务事理者也，羞独富者也。今之所谓仕士者，污漫者也，贼乱者也，恣睢者也，贪利者也，触抵者也，无礼义而唯权埶之嗜者也。古之所谓处士者，德盛者也，能静者也，修正者也，知命者也，著是者也。今之所谓处士者，无能而云能者也，无知而云知者也，利心无足而佯无欲者也，行伪险秽而彊高言谨悫者也，以不俗为俗，离纵而跂訾者也。"]]},{id:"p005",sentences:[["士君子之所能不能为：君子能为可贵，而不能使人必贵己；能为可信，而不能使人必信己；能为可用，而不能使人必用己。故君子耻不修，不耻见污；耻不信，不耻不见信；耻不能，不耻不见用。是以不诱于誉，不恐于诽，率道而行，端然正己，不为物倾侧，夫是之谓诚君子。《诗》云：“温温恭人，维德之基。”此之谓也。"]]},{id:"p006",sentences:[["士君子之容：其冠进，其衣逢，其容良，俨然，壮然，祺然，蕼然，恢恢然，广广然，昭昭然，荡荡然，是父兄之容也。其冠进，其衣逢，其容悫，俭然，恀然，辅然，端然，訾然，洞然，缀缀然，瞀瞀然，是子弟之容也。吾语汝学者之嵬容：其冠絻，其缨禁缓，其容简连；填填然，狄狄然，莫莫然，瞡瞡然，瞿瞿然，尽尽然，盱盱然，酒食声色之中则瞒瞒然，瞑瞑然；礼节之中则疾疾然，訾訾然；劳苦事业之中则儢儢然，离离然，偷儒而罔，无廉耻而忍𧫟訽：是学者之嵬也。"]]},{id:"p007",sentences:[["弟佗其冠，衶禫其辞，禹行而舜趋，是子张氏之贱儒也。正其衣冠，齐其颜色，嗛然而终日不言，是子夏氏之贱儒也。偷儒惮事，无廉耻而耆饮食，必曰君子固不用力，是子游氏之贱儒也。彼君子则不然。佚而不惰，劳而不僈，宗原应变，曲得其宜，如是，然后圣人也。"]]}];return(c,e)=>{const n=l("DaoTextReading");return o(),s("div",null,[e[0]||(e[0]=a("h1",{id:"荀子·第6篇·非十二子",tabindex:"-1"},[i("荀子·第6篇·非十二子 "),a("a",{class:"header-anchor",href:"#荀子·第6篇·非十二子","aria-label":'Permalink to "荀子·第6篇·非十二子"'},"​")],-1)),e[1]||(e[1]=a("p",null,"本篇讨论：批评诸家学说，申明所持的儒学立场。",-1)),e[2]||(e[2]=a("blockquote",null,[a("p",null,"原文已录入；段级白话、字词点查与三问解读待逐篇补充。原文录入不等于解读完成。")],-1)),e[3]||(e[3]=a("h2",{id:"【原典层】原文",tabindex:"-1"},[i("【原典层】原文 "),a("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),e[4]||(e[4]=a("p",null,"经典阅读保留段落；切换「竹简」可连续通读。此阶段按来源自然段呈现，不为未整理的段落预填释义。",-1)),d(n,{sections:t,"default-mode":"classic",tone:"ink",colophon:"荀子 · 非十二子","aria-label":"荀子·非十二子原文"}),e[5]||(e[5]=h("",8))])}}});export{f as __pageData,x as default};
